export function LandingPage() {
  return <><a className="skip-link" href="#main">Skip to content</a><Header /><main id="main"><section className="hero"><div className="container hero-grid"><div className="hero-copy"><a href="#open-source" className="release-pill"><span className="tiny-dot" />OPEN SOURCE · SELF-HOSTED · MCP <Arrow /></a><h1>Different agents.<br /><span>Same understanding.</span></h1><p className="hero-description">Shared context for MCP-compatible coding agents.<br className="desktop-break" /> Share progress, decisions, and handoffs across cloud-backed agents and compatible local-model workflows.</p><div className="hero-actions"><a className="site-button primary" href={`/downloads/${npmFile}`} download>Download Agent Context <Arrow diagonal /></a><a className="site-button text-button" href="/docs/quickstart/">Get started <Arrow /></a></div><div className="hero-install"><span className="prompt-symbol">$</span><code>{install}</code><CopyButton text={install} /></div><p className="hero-install-note">{config.npmPublished ? 'Install with npm, then run agent-context-mcp.' : 'After downloading, run this in the folder containing the .tgz file.'}</p><div className="hero-meta"><span>Node.js 24+</span><span>Runs on your machine</span><span>MIT license</span></div></div><div className="hero-visual"><div className="visual-label"><span>ONE PROJECT. A SHARED THREAD.</span><span>↙ TRY THE HANDOFF</span></div><WorkflowDemo /><div className="hero-caption"><span>↳</span>The next agent starts with context.</div></div></div><div className="container compatibility-strip"><span>YOUR TOOLS.<br /><strong>CONNECTED THROUGH MCP.</strong></span><div><span className="client-wordmark"><b>✳</b>Claude Code</span><span className="client-wordmark"><b>⌘</b>Codex</span><span className="client-wordmark"><b>◩</b>Cursor</span><span className="other-clients">+ other MCP clients</span></div></div></section>
    <section className="section compatibility-section" id="compatibility"><div className="container"><div className="section-intro"><p className="overline">YOUR MODEL. YOUR MACHINE. SHARED CONTEXT.</p><h2>Connect through MCP.<br /><span>Keep your choice of tools.</span></h2><p>Agent Context works through your agent’s MCP integration. Choose a compatible client, share one project record, and keep building.</p></div><div className="feature-grid"><article><span className="feature-icon">⌘</span><h3>Coding agents</h3><p>Use Claude Code, Codex, Cursor, VS Code/Copilot, Gemini CLI, or another client with MCP tools over stdio or Streamable HTTP. Enable the tools in your client.</p><a className="inline-link" href="/docs/clients/">Choose a client <Arrow /></a></article><article><span className="feature-icon">◫</span><h3>Windows, macOS, and Linux</h3><p>Designed for desktop systems with Node.js 24+. Local agents share a database path; remote agents connect to one reachable HTTP server.</p><a className="inline-link" href="/docs/compatibility/#systems">System requirements <Arrow /></a></article><article><span className="feature-icon">⬡</span><h3>Local-model workflows</h3><p>Use a tool-capable local model with an MCP-capable agent or host. Agent Context does not require a cloud model or a model API key.</p><a className="inline-link" href="/docs/compatibility/#local-models">Local model setup <Arrow /></a></article></div><p className="compatibility-note">Compatibility depends on the client, model, and tool configuration. Automated protocol checks passed locally; every client and operating-system combination has not been tested.</p></div></section>
    <section className="section team-section" id="teams"><div className="container"><div className="section-intro"><p className="overline">DIFFERENT COMPUTERS. ONE PROJECT RECORD.</p><h2>Your team connects.<br /><span>The context stays together.</span></h2><p>Run one shared server. Teammates keep their own coding agents and models, and connect through the network method that fits your team.</p></div><div className="feature-grid team-method-grid"><article><h3>Same Wi-Fi / LAN</h3><p>Connect to the host’s private IP on your office or home network. Configure the host firewall and exact allowlists.</p><a className="inline-link" href="/docs/team/#lan">LAN setup <Arrow /></a></article><article><h3>Private VPN</h3><p>Use a private encrypted network for teammates working from different locations, with a reachable private endpoint.</p><a className="inline-link" href="/docs/team/#vpn">VPN setup <Arrow /></a></article><article><h3>SSH tunnel</h3><p>Forward a local port to the shared server over SSH. Keep the context service bound to loopback on the host.</p><a className="inline-link" href="/docs/team/#ssh">SSH setup <Arrow /></a></article><article><h3>Shared HTTPS server</h3><p>Run on persistent infrastructure with a domain and TLS reverse proxy for an always-on team endpoint.</p><a className="inline-link" href="/docs/team/#https">HTTPS setup <Arrow /></a></article></div><p className="compatibility-note">Use the host’s token, the same project ID, and a unique agent ID per session. Plain LAN HTTP is unencrypted; prefer VPN, SSH, or HTTPS for routine team access. All token holders share access to the instance.</p></div></section>
    <section className="section product-section" id="product"><div className="container"><div className="section-intro"><p className="overline">THE PROJECT CONTINUES. THE CONTEXT SHOULD TOO.</p><h2>Your code has history.<br /><span>Give your agents some.</span></h2><p>A session ends. A different agent takes over. Keep the important context available before the next edit.</p></div><div className="feature-grid"><article><span className="feature-icon">▤</span><h3>A shared project memory.</h3><p>Architecture, progress, file references, and the decisions behind them. Stored durably and retrieved through MCP.</p><code>get_context(project_id)</code></article><article><span className="feature-icon">↗</span><h3>A handoff with a next step.</h3><p>Record what changed, what was tested, what is blocked, and exactly where the next agent should pick up.</p><code>record_update(kind: "handoff")</code></article><article><span className="feature-icon">◷</span><h3>Work with a clear owner.</h3><p>Claim tasks with expiring leases and version checks. See who holds a task before another agent starts it.</p><code>claim_task(expected_version)</code></article></div></div></section>
    <section className="section continuity-section" id="how-it-works"><div className="container continuity-grid"><div className="continuity-copy"><p className="overline">THREE MOMENTS. ONE CONTINUOUS BUILD.</p><h2>The handoff<br /><span>becomes the starting point.</span></h2><p className="section-description">Agents read and write the same project record. You choose the workflow; the server keeps the context available.</p><ol className="workflow-list"><li><span>01</span><div><h3>Read before editing.</h3><p>Load the project context and inspect current tasks.</p></div></li><li><span>02</span><div><h3>Record the meaningful changes.</h3><p>Keep decisions, file references, and test results with the work.</p></div></li><li><span>03</span><div><h3>Leave a useful next step.</h3><p>Write a handoff that the next session can act on.</p></div></li></ol><a className="inline-link" href="/docs/clients/">Set up the agent workflow <Arrow /></a></div><div className="context-example"><div className="example-header"><span>HANDOFF.MD</span><span>ILLUSTRATIVE PROJECT RECORD</span></div><div className="example-code"><p><span className="line-number">01</span><span className="code-comment"># Ready for the next session</span></p><p><span className="line-number">02</span></p><p><span className="line-number">03</span><span className="code-key">completed:</span> added login route</p><p><span className="line-number">04</span><span className="code-key">files:</span> src/auth.ts</p><p><span className="line-number">05</span><span className="code-key">decision:</span> validate sessions server-side</p><p><span className="line-number">06</span><span className="code-key">verification:</span> route tests passed</p><p><span className="line-number">07</span><span className="code-key">next:</span> connect the login screen</p></div><div className="example-call"><span>next agent →</span><code>get_context("launchpad")</code><span className="read-result">context retrieved ✓</span></div><p className="example-note">Saved records are agent reports. Verify the actual code and tests.</p></div></div></section>
    <section className="dashboard-section section"><div className="container"><div className="section-intro split-intro"><div><p className="overline">SEE THE THREAD. NOT JUST THE LATEST MESSAGE.</p><h2>A workspace for<br /><span>the whole build.</span></h2></div><p>Projects, contributing agents, task claims, searchable context, and activity. All in the React dashboard that ships with your local server.</p></div><div className="dashboard-preview" aria-label="Illustrative dashboard preview"><aside><span className="preview-brand">ac<span>·</span></span><span className="preview-nav active">◫ &nbsp; Overview</span><span className="preview-nav">▦ &nbsp; Projects</span><span className="preview-nav">✧ &nbsp; Agents</span><span className="preview-nav">≋ &nbsp; Activity</span><span className="preview-nav">⌘ &nbsp; Connect agents</span><small>ILLUSTRATIVE PREVIEW</small></aside><div className="preview-main"><div className="preview-topbar"><span>Workspace / Overview</span><span>LOCAL INSTANCE</span></div><div className="preview-content"><div className="preview-title"><div><span>YOUR WORKSPACE, IN SYNC.</span><h3>Everything that comes next.</h3></div><span className="preview-button">+ New project</span></div><div className="preview-metrics">{[['Projects', '2'], ['Open tasks', '3'], ['Recent updates', '8'], ['Contributing agents', '2']].map(([title, value]) => <div key={title}><span>{title}</span><strong>{value}</strong><small>Sample project data</small></div>)}</div><div className="preview-panels"><div><h4>Your projects</h4><p><span className="project-mark">LP</span><span><strong>Launchpad</strong><small>launchpad / shared context</small></span><b>↗</b></p><p><span className="project-mark">DK</span><span><strong>Developer kit</strong><small>developer-kit / shared context</small></span><b>↗</b></p></div><div><h4>Latest handoff</h4><div className="preview-handoff"><span>↗</span><div><strong>Login route complete</strong><p>Next: connect the login screen.</p><small>Claude · launchpad · handoff</small></div></div></div></div></div></div></div><div className="dashboard-caption"><span>React dashboard included. No separate frontend server.</span><a href="/docs/quickstart/">Run your own workspace <Arrow /></a></div></div></section>
    <InstallSteps />
    <section className="section open-source-section" id="open-source"><div className="container open-source-grid"><div><p className="overline">YOURS TO RUN. OPEN TO IMPROVE.</p><h2>Read it. Run it.<br /><span>Make it yours.</span></h2><p>Open source under the MIT license. Keep your data on your infrastructure, inspect how it works, and help shape what comes next.</p><div className="hero-actions"><a className="site-button primary" href={sourceUrl}>{config.repositoryUrl ? 'Explore on GitHub' : 'Download the source'} <Arrow diagonal /></a><a className="site-button text-button" href="/docs/contributing/">Contribute <Arrow /></a></div></div><div className="open-source-facts"><div><span>LICENSE</span><strong>MIT</strong><a href="/docs/LICENSE.txt">Read the license ↗</a></div><div><span>DEPLOYMENT</span><strong>Self-hosted</strong><p>One trusted user or team per instance.</p></div><div><span>STORAGE</span><strong>Local SQLite</strong><p>History stays outside the installation directory.</p></div><div><span>PROTOCOL</span><strong>MCP</strong><p>10 tools, plus a project resource and resume prompt.</p></div></div></div></section>
    <section className="section faq-section"><div className="container faq-grid"><div><p className="overline">GOOD QUESTIONS.</p><h2>A little more<br /><span>context.</span></h2></div><div className="faq-items"><details><summary>Will it work with any AI coding agent?</summary><p>It works with clients that support MCP tools over stdio or Streamable HTTP. An AI model or chat app without an MCP integration cannot connect by itself. See the <a href="/docs/compatibility/">compatibility guide</a> for requirements and verification limits.</p></details><details><summary>Can I use a local model?</summary><p>Yes, through an MCP-capable agent or host using a model that can call tools reliably. A local inference runtime such as Ollama or llama.cpp needs an MCP-capable host or integration in the workflow. Model, template, and client support determine whether tool calls work. See <a href="/docs/compatibility/#local-models">local model setup</a>.</p></details><details><summary>Can agents on different computers share context?</summary><p>Yes. Connect every client to one running MCP server over Streamable HTTP, using its reachable URL and instance token. Connect over the same Wi-Fi/LAN, a private VPN, an SSH tunnel, or an HTTPS server. Follow the <a href="/docs/team/">team connection guide</a>. The public website serves documentation and downloads; you run the MCP service separately.</p></details><details><summary>Does it automatically read my agents' conversations?</summary><p>Agents use MCP tools to read and record engineering context. Add the workflow to the instruction file your client reads, such as AGENTS.md, CLAUDE.md, GEMINI.md, or editor rules so each session reads the shared record and leaves a handoff. Initial project knowledge comes from an agent inspecting your repository and recording it.</p></details><details><summary>Why does the dashboard ask for an access token?</summary><p>The token protects the local HTTP service. Run <code>agent-context-mcp token</code> in another terminal and paste its output into the dashboard. If you use a custom database, pass the same --db path to both commands.</p></details><details><summary>Can I use it with my existing project?</summary><p>Yes. Run your agents from the existing repository and connect them to this server. Give every agent the same project ID. The server stores context in a separate SQLite file and does not edit the repository itself.</p></details><details><summary>Can multiple agents edit the same project?</summary><p>Yes. Task claims and version checks coordinate ownership, and expired leases can be reclaimed. Claims apply to tasks; agents should still check file overlap and use separate Git worktrees when editing concurrently.</p></details><details><summary>Is there a hosted account or software subscription?</summary><p>This release is self-hosted and MIT licensed. There is no product subscription or hosted signup. You operate the server and infrastructure, and any AI tools you connect retain their own accounts and costs.</p></details></div></div></section>
    <section className="closing-section"><div className="container"><p className="overline">THE NEXT AGENT IS READY.</p><h2>Give it a good<br /><span>place to start.</span></h2><a className="site-button primary" href={`/downloads/${npmFile}`} download>Download v{config.version} <Arrow diagonal /></a><p>Node.js 24+ · Local-first · MIT licensed</p></div></section>
  </main><Footer /></>;
}

const docPages = {
  overview: { title: 'Keep your agents on the same page.', subtitle: 'Start a local instance, connect your coding tools, and make every handoff useful.' },
  quickstart: { title: 'Your first shared workspace.', subtitle: 'Download, install, and open the local dashboard.' },
  clients: { title: 'Connect your coding agents.', subtitle: 'Use the same project ID and database across clients.' },
  compatibility: { title: 'Choose your agent, system, and model.', subtitle: 'Understand MCP requirements, local models, shared connections, and what has been verified.' },
  team: { title: 'One team. One shared context.', subtitle: 'Connect over the same Wi-Fi, a private VPN, an SSH tunnel, or an HTTPS server.' },
  'self-hosting': { title: 'Run it on your terms.', subtitle: 'Understand credentials, storage, backups, and the instance trust boundary.' },
  troubleshooting: { title: 'Get back to building.', subtitle: 'Resolve installation paths, tokens, network errors, client setup, and website deployment.' },
  contributing: { title: 'Build it with us.', subtitle: 'Read the source, run the checks, and propose focused improvements.' },
};
export const docs = Object.entries(docPages).map(([id, page]) => ({ id, ...page, href: id === 'overview' ? '/docs/' : `/docs/${id}/` }));

function ClientSetup() {
  const [client, setClient] = useState('generic');
  const profile = CLIENT_PROFILES.find((item) => item.id === client);
  const configuration = JSON.stringify(clientConfiguration({ client, database: '/absolute/path/to/shared/context.sqlite3' }), null, 2);
  return <><h2>Choose your MCP client</h2><p>Any coding agent with MCP tool support can connect over stdio or Streamable HTTP, regardless of the AI model it uses. Agents without MCP support need an MCP integration.</p><label htmlFor="mcp-client">Client</label><select id="mcp-client" value={client} onChange={(event) => setClient(event.target.value)}>{CLIENT_PROFILES.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><p>{profile.location} Merge with existing settings rather than replacing the file.</p><Code title="GENERATE YOUR CONFIGURATION">{`agent-context-mcp config --client ${client} --db /absolute/path/to/shared/context.sqlite3`}</Code><Code title="EXAMPLE JSON · REPLACE THE DATABASE PATH">{configuration}</Code><p>Use the same absolute database path in every local agent and the dashboard. Install the package first, enable MCP tools in your client, then start a fresh agent session. If the executable cannot be found, use its absolute path in the command field.</p><p>For a client on another computer, connect to the server’s reachable /mcp URL with a bearer token and Streamable HTTP support. Local stdio paths and localhost refer to the computer running the client.</p></>;
}

function CompatibilityGuide() {
  return <><h2>What makes an agent compatible?</h2><p>Your coding agent or host needs an MCP client that can list and call tools over stdio or Streamable HTTP. The AI model can be local or cloud-hosted. A plain model endpoint does not automatically read or write Agent Context.</p><p>Client configuration presets are available for Cursor, VS Code/Copilot, Gemini CLI, and generic MCP clients, alongside the Claude Code and Codex setup commands. These are configuration examples; every third-party client UI has not been tested.</p><a className="inline-link" href="/docs/clients/">Generate client configuration <Arrow /></a><h2 id="systems">Operating systems and requirements</h2><div className="compatibility-table-wrap"><table className="compatibility-table"><thead><tr><th scope="col">System</th><th scope="col">Requirements</th><th scope="col">Verification</th></tr></thead><tbody><tr><th scope="row">Linux</th><td>Node.js 24+, npm, writable local data directory</td><td>Local package installation and automated service checks passed in this environment.</td></tr><tr><th scope="row">macOS</th><td>Node.js 24+, npm, writable local data directory</td><td>Designed to support it; CI configured, but results are not verified here.</td></tr><tr><th scope="row">Windows</th><td>Node.js 24+, npm, writable local data directory</td><td>Designed to support it; CI configured, but results are not verified here.</td></tr></tbody></table></div><p>The npm release bundles the React dashboard and server libraries. Python and native dependency compilation are not required. The AI model’s RAM, GPU, and storage needs are separate from the context server’s requirements.</p><h2 id="local-models">Using a local model</h2><p>Use a local inference runtime such as Ollama or llama.cpp with a tool-capable model and an MCP-capable host. The host can be your coding-agent application or another runtime with an MCP integration.</p><div className="model-flow" role="img" aria-label="A local model exchanges tool requests with an MCP-capable agent or host, which reads and records shared context in Agent Context"><span>Local model</span><b aria-hidden="true">↔</b><span>MCP-capable<br />agent or host</span><b aria-hidden="true">↔</b><span>Agent Context</span></div><ol><li>Start your local model and select it in an agent or host that supports both that model endpoint and MCP tools.</li><li>Install Agent Context and configure its stdio command, or connect to your running HTTP instance.</li><li>Enable the MCP tools and use the same project ID as your other agents.</li><li>Ask the agent to call list_projects, record a test handoff, and read it back with get_context. Confirm the actual tool calls, not just a text description.</li></ol><Code title="GENERATE LOCAL MCP CONFIGURATION">{'agent-context-mcp config --client generic --db /absolute/path/to/shared/context.sqlite3'}</Code><p>Agent Context does not require a model API key. A fully local workflow is possible when the model and host both run locally and use local services. Hosted models and any external tools you enable keep their own network and account requirements.</p><p>Tool-use reliability depends on the model, its template, and the host’s tool execution. We have not benchmarked or validated every local model. Start with a small test project before relying on automatic handoffs.</p><p>Runtime references: <a href="https://github.com/ollama/ollama/blob/main/docs/capabilities/tool-calling.mdx">Ollama tool calling</a> and <a href="https://github.com/ggml-org/llama.cpp/blob/master/tools/server/README.md">llama.cpp server documentation</a>.</p><h2 id="shared-context">Sharing context across systems</h2><p>Choose a <a href="/docs/team/">team connection method: Wi-Fi/LAN, private VPN, SSH tunnel, or HTTPS</a>.</p><ul><li><strong>Same computer:</strong> use the same absolute SQLite database path in the dashboard and every stdio configuration.</li><li><strong>Different computers or cloud agents:</strong> connect to one persistent server using its reachable /mcp URL, Streamable HTTP, and a bearer token. Use HTTPS for remote access.</li><li><strong>Same project:</strong> use the same project ID and a different agent ID for each session. Agents must record their work so the next agent can read it.</li></ul><p>Do not share SQLite by placing a live database on a network filesystem. Use one HTTP server to share access remotely. A cloud agent cannot reach your laptop’s localhost without a separately configured network connection.</p><h2>What the public website provides</h2><p>This website hosts the documentation and downloadable releases. It does not host your project database or act as your MCP endpoint. Run the installed server locally or on your own persistent infrastructure.</p><h2>What is verified today?</h2><p>Automated checks cover shared handoffs, MCP SDK communication, authentication, task claims, backups, and configuration output. Two subprocess tests are skipped in this restricted environment. Browser interactions, every named coding client, all operating systems, and local-model combinations still need direct verification.</p><h2>Context is recorded work</h2><p>The server does not automatically capture conversations or inspect your repository. Add the shared workflow to each agent’s instructions: read context before editing, claim a task, record meaningful changes and test results, and leave a handoff before stopping.</p></>;
}

function TeamGuide() {
  return <><h2>Choose how your team connects</h2><p>Run one Agent Context server with one persistent database. Every teammate connects their MCP client to that server; their coding agent and model can run on their own computer.</p><div className="compatibility-table-wrap"><table className="compatibility-table"><thead><tr><th scope="col">Method</th><th scope="col">Best fit</th><th scope="col">Connection</th></tr></thead><tbody><tr><td><a href="#lan">Same Wi-Fi / LAN</a></td><td>One trusted office or home network</td><td>Host’s private IP and port 8765</td></tr><tr><td><a href="#vpn">Private VPN</a></td><td>Teammates in different locations</td><td>Private VPN address or HTTPS name</td></tr><tr><td><a href="#ssh">SSH tunnel</a></td><td>Teammates who already have SSH access</td><td>Encrypted tunnel to a loopback-only service</td></tr><tr><td><a href="#https">Shared HTTPS server</a></td><td>An always-on service for the team</td><td>Domain with TLS and an instance token</td></tr></tbody></table></div><p>All examples use <code>./data/context.sqlite3</code> on the host. Run commands from the same directory, or replace it with the absolute path to your existing database. Stop the old service first if it already uses port 8765.</p><h2 id="lan">1. Same Wi-Fi or LAN</h2><p>Find the host computer’s private IPv4 address in its network settings. For example, if it is 192.168.1.50, run this on the host. Replace that example IP in both allowlists with your actual address.</p><Code>{'agent-context-mcp --host 0.0.0.0 --port 8765 --db ./data/context.sqlite3 --allowed-host 192.168.1.50:8765 --allowed-origin http://192.168.1.50:8765'}</Code><p>In another host terminal, retrieve the token:</p><Code>{'agent-context-mcp token --db ./data/context.sqlite3'}</Code><p>Teammates on the same network open <code>http://192.168.1.50:8765/dashboard</code> or configure their MCP client as follows:</p><Code title="CLIENT CONNECTION FIELDS">{'Transport: Streamable HTTP\nURL: http://192.168.1.50:8765/mcp\nHeader: Authorization: Bearer <instance-token>'}</Code><p>Allow inbound TCP port 8765 in the host firewall only from your team’s private subnet. The host must stay awake and connected. A router DHCP reservation can keep its IP stable. Guest Wi-Fi or client isolation may prevent computers from reaching each other.</p><p className="doc-note">Plain HTTP does not encrypt the token or project context. Use this only for a deliberate test on a trusted private network. Use a VPN, SSH tunnel, or HTTPS for encrypted team access. Do not forward port 8765 from your internet router.</p><h2 id="vpn">2. Private VPN for different networks</h2><p>A private VPN such as Tailscale or a managed WireGuard network can connect teammates without exposing the application port publicly. With Tailscale Serve, join the host and teammates to an authorized tailnet and allow access through its network policy.</p><p>On the host, use its actual Tailscale HTTPS hostname in place of the example below:</p><Code>{'agent-context-mcp --host 127.0.0.1 --db ./data/context.sqlite3 --allowed-host machine.tailnet-name.ts.net --allowed-origin https://machine.tailnet-name.ts.net'}</Code><p>In another host terminal, configure the private HTTPS proxy:</p><Code>{'tailscale serve --bg http://127.0.0.1:8765\ntailscale serve status'}</Code><p>Use the exact HTTPS address reported by Serve, with <code>/mcp</code> appended, in each client. If its hostname differs from your allowlists, update the server command and restart it. Keep the Agent Context bearer token enabled. Serve is private to your tailnet; a public sharing feature is not required.</p><p><a href="https://tailscale.com/docs/use-cases/application-testing/share-local-dev-server-with-team">Tailscale team-sharing guide</a> · <a href="https://tailscale.com/docs/reference/tailscale-cli/serve">Serve command reference</a></p><h2 id="ssh">3. SSH tunnel</h2><p>If teammates already have SSH access to the host, keep Agent Context bound to loopback:</p><Code title="ON THE HOST">{'agent-context-mcp --host 127.0.0.1 --db ./data/context.sqlite3'}</Code><p>Each teammate opens a tunnel in their own terminal. Replace the SSH username and hostname with the host’s actual details:</p><Code title="ON EACH TEAMMATE’S COMPUTER">{'ssh -N -L 8765:127.0.0.1:8765 username@server-address'}</Code><p>Keep the tunnel open. The teammate’s client connects to <code>http://127.0.0.1:8765/mcp</code> with the host’s instance token. Here localhost works because SSH forwards that port to the shared server. Stop any local service using port 8765 before opening the tunnel. SSH access and firewall permissions must already be configured.</p><h2 id="https">4. Always-on HTTPS server</h2><p>Run the service on a persistent server, keep it on loopback, and put a TLS reverse proxy in front of it:</p><Code>{'agent-context-mcp --host 127.0.0.1 --db ./data/context.sqlite3 --allowed-host context.example.com --allowed-origin https://context.example.com'}</Code><Code title="EXAMPLE CADDYFILE · REPLACE THE DOMAIN">{'context.example.com {\n    reverse_proxy 127.0.0.1:8765\n}'}</Code><p>Point the actual domain at the server, configure the reverse proxy and TLS, and allow the needed HTTPS traffic. Teammates connect to <code>https://context.example.com/mcp</code> with the instance token. Configure the service to restart after reboot and back up its persistent database. See the <a href="/docs/self-hosting/">self-hosting guide</a> and <a href="https://caddyserver.com/docs/quick-starts/reverse-proxy">Caddy reverse-proxy documentation</a>.</p><h2>One shared project, from every computer</h2><p>Share the server endpoint and token through a private channel. Select Streamable HTTP in each agent’s MCP settings, use the same project ID, and give each session a unique agent ID. Ask one agent to record a test handoff and another to read it before starting real work.</p><p>Every token holder can access every project in that instance. There are no individual accounts or project permissions yet. Keep separate instances for unrelated teams. Teammates do not need separate local databases, and must not share a live SQLite file through a network drive.</p><h2>Connection troubleshooting</h2><ul><li><strong>Cannot connect:</strong> check the host is awake, IP and port are correct, the firewall allows your network, and any VPN or SSH tunnel is running.</li><li><strong>421:</strong> add the exact hostname or IP with its port to --allowed-host. Do not use 0.0.0.0 as the client URL.</li><li><strong>403:</strong> add the dashboard’s exact browser origin, including scheme and non-default port, to --allowed-origin.</li><li><strong>401:</strong> retrieve the token on the host using the same --db and credential settings as its running service.</li><li><strong>Empty or different history:</strong> check every client uses the same server and project ID.</li></ul><p>These are setup recipes, not a report that a VPN, tunnel, firewall rule, or hosted server has been configured for you. Verify connectivity on your own network. The Vercel website serves documentation and downloads; it is not the shared MCP server.</p></>;
}

function TroubleshootingGuide() {
  return <><h2>Start with the actual error</h2><p>Check node --version, npm --version, and agent-context-mcp --version. Read the first failed step as well as the final error. For a bug report, include versions, operating system, installation method, and minimal reproduction in <a href="https://github.com/suyashB45/agent-context/issues">GitHub issues</a>. Remove tokens and private context.</p><h2 id="package-path">Package file not found (ENOENT)</h2><p>A tarball retry warning does not prove corruption. ENOENT means npm cannot find the file at the supplied path. After downloading the package, run this from its download folder:</p><Code>{`npm install -g ./${npmFile}`}</Code><p>From the source repository, generate the ignored package first:</p><Code>{`npm ci\nnpm run build\nnpm pack --ignore-scripts --pack-destination dist/npm\nnpm install -g ./dist/npm/${npmFile}`}</Code><p>If the downloaded file is incomplete, download it again and compare its SHA-256 digest with <a href="/downloads/release.json">release checksums</a>. A checksum verifies a matching file, not publisher identity.</p><h2>Command not found or the wrong version starts</h2><p>Use Node.js 24+. Check npm prefix -g and the executable directory in your terminal and editor PATH. Use the absolute executable path in client settings if needed. Deactivate the old Python virtual environment if it selects the Python prototype. From source, run node bin/agent-context-mcp.mjs --version after building.</p><h2>Port already in use</h2><p>Stop the old service or choose --port 8766, then update client URLs and any Host/Origin allowlists. A local service on port 8765 also prevents an SSH tunnel from binding that port.</p><h2 id="credentials">Token rejected or history is different</h2><p>Retrieve the token on the running host using its exact database path and credential settings. A teammate’s separate local token will not authenticate to the shared host. Relative database paths depend on the current directory. Ensure every client uses the same host or local database and the same project ID.</p><p>Use only one token source. Restart after token rotation and update clients. Reloading the dashboard clears its in-memory token.</p><h2 id="network">Connection and HTTP errors</h2><ul><li><strong>Timeout or refused:</strong> check service, host IP, firewall, VPN, tunnel, and Wi-Fi client isolation.</li><li><strong>401:</strong> supply the running host’s token in the Authorization header.</li><li><strong>403:</strong> add the exact browser Origin, including scheme and non-default port.</li><li><strong>421:</strong> allow the exact Host and port. Never use 0.0.0.0 as a client URL.</li><li><strong>413:</strong> split an oversized update.</li><li><strong>429 or 503:</strong> follow Retry-After when present and retry later.</li></ul><p>Follow the <a href="/docs/team/">team network guide</a> for LAN, VPN, SSH, and HTTPS. Localhost reaches the client’s own machine unless you explicitly configured forwarding.</p><h2>Connected agent does not record work</h2><p>Enable MCP tools and start a fresh session. A subprocess setup needs the stdio action. Add the shared workflow to the instruction file the agent reads and verify actual tool calls using a test project. Local models also need compatible templates, tool use, and an MCP-capable host.</p><h2 id="vercel">Vercel build or preset mismatch</h2><p>Import the repository root (./), choose Other and Node.js 24.x, set build command npm run vercel:build and output directory site/dist. Ensure the current commit includes vercel.json and matching package/site versions. npm run site:serve is only a local preview.</p><p>The Vercel site hosts docs and downloads; the persistent MCP server runs separately. For further detail, see the <a href="https://github.com/suyashB45/agent-context/blob/main/docs/troubleshooting.md">repository troubleshooting guide</a>.</p></>;
}

function DocBody({ page }) {
  if (page === 'troubleshooting') return <TroubleshootingGuide />;
  if (page === 'team') return <TeamGuide />;
  if (page === 'compatibility') return <CompatibilityGuide />;
  if (page === 'quickstart') return <><h2>1. Download and install</h2><p>Install Node.js 24 or newer. Download the npm package and open a terminal in the folder containing the .tgz file, usually your Downloads folder. The command below expects the file to be in your current directory.</p><a className="site-button secondary small" href={`/downloads/${npmFile}`} download>Download v{config.version} <Arrow diagonal /></a><Code>{install}</Code>{!config.npmPublished && <p className="doc-note">The downloadable package works now. Installation directly by registry name becomes available after the npm release.</p>}<h2>2. Start the server</h2><Code>{'agent-context-mcp'}</Code><p>Open <code>http://127.0.0.1:8765/dashboard</code>. Keep this terminal running.</p><h2>3. Retrieve the access token</h2><Code>{'agent-context-mcp token'}</Code><p>Run this in a second terminal, then paste the output into the dashboard. Use the same <code>--db</code> option if you selected a custom database.</p><h2>4. Create a project and connect an agent</h2><p>Create a project in the dashboard, then use its Connect agents screen or the <a href="/docs/clients/">client setup guide</a>. Ask the first agent to inspect your repository and record its architecture, progress, and next steps.</p><h2 id="from-source">Installing from the source repository</h2><p>If you cloned or downloaded the source, run these commands from the repository root containing package.json. The built package belongs in <code>dist/npm/</code>.</p><Code>{`npm ci\nnpm run build\nnpm pack --ignore-scripts --pack-destination dist/npm\nnpm install -g ./dist/npm/${npmFile}`}</Code><p>If the package is already built, just run the last command. Then start <code>agent-context-mcp</code> and open the dashboard as described above.</p><p>Need help? See <a href="/docs/troubleshooting/">installation and connection troubleshooting</a>.</p><h2>File not found (ENOENT)</h2><p>This means npm cannot find the package at the path you supplied. For a downloaded package, open a terminal in its download folder. For a source checkout, use <code>{`./dist/npm/${npmFile}`}</code> after building it.</p><h2>Using an existing database</h2><Code>{'agent-context-mcp --db /absolute/path/to/context.sqlite3\nagent-context-mcp token --db /absolute/path/to/context.sqlite3'}</Code><p>The Node release reads the earlier SQLite schema. Records are not moved or cleared. Stop the old server if it occupies port 8765.</p></>;
  if (page === 'clients') return <><ClientSetup /><p>Using a local model or another operating system? Read the <a href="/docs/compatibility/">compatibility guide</a>. Connecting teammates on separate computers? Follow the <a href="/docs/team/">LAN, VPN, SSH, or HTTPS setup guide</a>.</p><h2>Local agents over stdio</h2><p>Each agent starts its own process and shares the configured SQLite file. The explicit <code>stdio</code> action is required because the default npm command starts the dashboard.</p><Code>{'codex mcp add agent-context -- agent-context-mcp stdio --db /absolute/path/to/shared/context.sqlite3\nclaude mcp add --scope user agent-context -- agent-context-mcp stdio --db /absolute/path/to/shared/context.sqlite3'}</Code><h2>Agents over HTTP</h2><p>The following commands connect a client on the same computer as the server. For a teammate’s computer, use the endpoint and host token from the <a href="/docs/team/">team guide</a>. Do not generate a separate local token on each teammate’s computer.</p><p>Keep the server running. Export its token in the terminal that launches your client:</p><Code>{'export AGENT_CONTEXT_TOKEN="$(agent-context-mcp token)"\ncodex mcp add agent-context --url http://127.0.0.1:8765/mcp --bearer-token-env-var AGENT_CONTEXT_TOKEN'}</Code><p>For Claude Code:</p><Code>{'claude mcp add --scope user --transport http agent-context http://127.0.0.1:8765/mcp --header "Authorization: Bearer $AGENT_CONTEXT_TOKEN"'}</Code><p>Claude saves the resolved token in its configuration. Protect that file. On PowerShell, use <code>$env:AGENT_CONTEXT_TOKEN = agent-context-mcp token</code> and the same environment-variable syntax in the header.</p><h2>Make the shared context part of the workflow</h2><p>Add this instruction to the file your agent reads in the repository you are building, such as AGENTS.md, CLAUDE.md, GEMINI.md, or editor rules:</p><Code title="AGENT INSTRUCTIONS">{instructions}</Code><p>Use a different agent ID per session, and the same project ID in every client. Restart existing agent sessions after changing MCP registration.</p></>;
  if (page === 'self-hosting') return <><p>Connecting teammates? Use the <a href="/docs/team/">Wi-Fi/LAN, VPN, SSH, and HTTPS setup guide</a>.</p><h2>Public website and running MCP server</h2><p>The Vercel website serves documentation and downloads. Run the MCP service on your computer or persistent infrastructure; choose a reachable LAN, private VPN, SSH-tunnel, or HTTPS endpoint for agents on other machines. See <a href="/docs/compatibility/#shared-context">shared context across systems</a>.</p><h2>One instance, one trust boundary</h2><p>Every token holder can read and write every project in the instance. Agent IDs are self-reported. Run separate instances for unrelated users or teams.</p><h2>Choose a durable data path</h2><Code>{'agent-context-mcp --db /srv/agent-context/context.sqlite3 --token-file /path/to/token'}</Code><p>Set <code>AGENT_CONTEXT_DB</code> as an alternative. New installations default to the OS user data directory, outside the npm installation. Keep SQLite on a local durable disk.</p><h2>Remote access</h2><p>Use HTTPS through a reverse proxy, keep the application port private, and configure exact Host and Origin allowlists:</p><Code>{'agent-context-mcp --allowed-host context.example.com --allowed-origin https://context.example.com --db /srv/agent-context/context.sqlite3 --token-file /path/to/token'}</Code><p>Authentication uses a pre-provisioned bearer token. This release does not provide interactive OAuth login or tenant permissions.</p><h2>Health and request limits</h2><p><code>/healthz</code> reports process liveness. Authenticated <code>/readyz</code> checks database readability. The defaults are a 256 KiB body cap, 600 protected requests per minute, and 32 protected concurrent requests. Use <code>--help</code> for configuration options.</p><h2>Back up before an upgrade</h2><Code>{'agent-context-mcp backup --db /path/to/context.sqlite3 --output /path/to/new-backup.sqlite3\nagent-context-mcp check --db /path/to/new-backup.sqlite3'}</Code><p>Backups include committed WAL records and refuse to overwrite files. Test restores. Stop all clients before replacing a database, and preserve its original WAL sidecars separately.</p><h2>Containers</h2><p>The source includes Docker Compose and a multi-stage Node image with a non-root user, a read-only filesystem, and a persistent volume. Build from source and configure the instance token before exposing the service.</p></>;
  if (page === 'contributing') return <><h2>Start with the source</h2><p>Agent Context is MIT licensed. The source release includes the Node service, React dashboard, tests, deployment files, and contributor documentation.</p><a className="site-button secondary small" href={sourceUrl}>Explore the source <Arrow diagonal /></a><h2>Run the development checks</h2><Code>{'npm ci\nnpm run build\nnpm run check\nnpm run docs:check\nnpm test\nnpm start -- --db ./data/dev.sqlite3'}</Code><p>In another terminal, run node bin/agent-context-mcp.mjs token --db ./data/dev.sqlite3 from the same source directory. Preview the product website separately with npm run vercel:build and npm run site:serve. Include reproduction steps, the Node version, OS, and relevant validation in reports or pull requests. Never attach a real access token or private database.</p><h2>Useful contribution areas</h2><ul><li>Improve context retrieval, filtering, and handoff quality.</li><li>Clarify agent setup and stale-claim recovery.</li><li>Add meaningful failure, backup, restore, and protocol tests.</li><li>Improve accessible dashboard and documentation workflows.</li></ul><h2>Community expectations</h2><p>Be respectful, explain technical concerns with evidence, and welcome contributors at different experience levels. The source release includes CONTRIBUTING.md and CODE_OF_CONDUCT.md.</p><h2>Help and contributions</h2><p>Use <a href="https://github.com/suyashB45/agent-context/issues">GitHub issues</a> for reproducible bugs and feature proposals. Read the <a href="https://github.com/suyashB45/agent-context/blob/main/CONTRIBUTING.md">contributor guide</a> and <a href="https://github.com/suyashB45/agent-context/blob/main/docs/release.md">maintainer release guide</a>.</p><h2>Security reports</h2><p>Use an established private maintainer channel for suspected vulnerabilities. Remove credentials and private context from reproductions. Email the maintainer privately at <a href="mailto:suyashbalasubramaniam@gmail.com">suyashbalasubramaniam@gmail.com</a>. Include the affected version and a minimal reproduction; remove credentials and private records.</p></>;
  return <><div className="doc-card-grid">{docs.filter((item) => item.id !== 'overview').map((item) => <a className="doc-link-card" href={item.href} key={item.id}><span>{item.title}</span><p>{item.subtitle}</p><Arrow /></a>)}</div><h2>Start here</h2><p>Install the downloadable package or build from source with the <a href="/docs/quickstart/">quick start</a>. Then choose a <a href="/docs/clients/">client</a> and verify a handoff. For several computers, use the <a href="/docs/team/">team guide</a>. The active product is Node.js/React; Python setup is historical.</p><p>{config.npmPublished ? 'The npm registry release is published according to the maintained release configuration.' : 'The public npm registry release is pending until verified by the maintainer.'} Downloadable artifacts are built from this source; a website build alone does not prove public deployment or passed cross-platform CI.</p><h2>What Agent Context does</h2><p>It keeps structured project context available through MCP. One agent records the work; another reads the handoff before continuing. The dashboard and coding agents use the same database.</p><h2>The core loop</h2><ol><li>Read project context and current tasks.</li><li>Claim the next task using its current version.</li><li>Inspect the repository, implement, and verify changes.</li><li>Record meaningful updates and leave a useful handoff.</li></ol><h2>Recorded context, with evidence</h2><p>The server stores the facts agents report. It does not automatically capture chat history, execute tests, or validate file changes. Include file paths, commit references, rationale, test results, and next actions in the record.</p><h2>Agents, systems, and local models</h2><p>Use an MCP-capable agent or host on a supported desktop system with Node.js 24+. Local models need reliable tool calling and an MCP integration. See <a href="/docs/compatibility/">compatibility, requirements, and verification status</a>.</p><h2>Built to run locally</h2><p>Node.js 24 and local SQLite provide the runtime. React assets and server libraries are bundled into the npm package. No model API key or separate frontend service is required.</p></>;
}

export function DocsPage({ page = 'overview' }) {
  const current = docPages[page] || docPages.overview;
  return <><a className="skip-link" href="#main">Skip to content</a><Header docs /><main id="main" className="container docs-layout"><aside className="docs-sidebar"><a className="docs-back" href="/">← Back to the product</a><p className="overline">DOCUMENTATION</p><nav aria-label="Documentation">{docs.map((item) => <a key={item.id} href={item.href} aria-current={item.id === page ? 'page' : undefined}>{item.id === 'overview' ? 'Overview' : item.id === 'clients' ? 'Connect agents' : item.id === 'compatibility' ? 'Compatibility & local models' : item.id === 'team' ? 'Team connections' : item.id === 'self-hosting' ? 'Self-hosting' : item.id === 'troubleshooting' ? 'Troubleshooting' : item.id === 'contributing' ? 'Contributing' : 'Quick start'}</a>)}</nav><a className="inline-link" href={`/downloads/${npmFile}`} download>Download v{config.version} ↗</a></aside><article className="docs-content"><p className="overline">AGENT CONTEXT / DOCS</p><h1>{current.title}</h1><p className="docs-subtitle">{current.subtitle}</p><DocBody page={page} /></article></main><Footer /></>;
}
